<?php require __DIR__.'/_init.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'){$pdo->prepare('DELETE FROM print_options WHERE id=?')->execute([(int)$_POST['id']]);flash('success','گزینه حذف شد.');}else{$id=(int)($_POST['id']??0);$group=trim((string)($_POST['option_group']??''));$name=trim((string)($_POST['option_name']??''));$delta=(int)($_POST['price_delta']??0);$pid=(int)($_POST['product_id']??0)?:null;$active=isset($_POST['is_active'])?1:0;if($group===''||$name===''){flash('error','گروه و نام گزینه الزامی است.');}elseif($id){$pdo->prepare('UPDATE print_options SET product_id=?,option_group=?,option_name=?,price_delta=?,is_active=? WHERE id=?')->execute([$pid,$group,$name,$delta,$active,$id]);flash('success','گزینه به‌روزرسانی شد.');}else{$pdo->prepare('INSERT INTO print_options(product_id,option_group,option_name,price_delta,is_active,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$pid,$group,$name,$delta,$active]);flash('success','گزینه اضافه شد.');}}header('Location: '.site_url('admin/print-options.php'));exit;}
$products=$pdo->query('SELECT id,name FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT o.*,p.name product_name FROM print_options o LEFT JOIN products p ON p.id=o.product_id ORDER BY o.option_group,o.sort_order,o.id')->fetchAll();render_header('گزینه‌های چاپ');?><main class="container"><div class="page-title"><h1>گزینه‌های چاپ</h1><p>تعریف جنس، ابعاد، روکش، تیراژ یا هر ویژگی و مبلغ اضافه.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/coupons.php'))?>">تخفیف‌ها</a><a href="<?=e(site_url('admin/settings.php'))?>">تنظیمات سایت</a></aside><section class="admin-content"><div class="form-card"><h2>افزودن گزینه</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>گروه (مثلاً جنس کاغذ)</label><input name="option_group" required></div><div class="form-group"><label>نام گزینه</label><input name="option_name" required></div><div class="form-group"><label>مبلغ اضافه برای هر واحد (تومان، منفی هم مجاز)</label><input type="number" name="price_delta" value="0"></div><div class="form-group"><label>محصول (خالی یعنی همه)</label><select name="product_id"><option value="0">همه محصولات</option><?php foreach($products as $pr):?><option value="<?=$pr['id']?>"><?=e($pr['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label><input type="checkbox" name="is_active" checked> فعال</label></div></div><button class="btn">ذخیره گزینه</button></form></div><div class="table-wrap"><table class="table"><tr><th>گروه</th><th>گزینه</th><th>محصول</th><th>تغییر قیمت</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['option_group'])?></td><td><?=e($r['option_name'])?></td><td><?=e($r['product_name']??'همه محصولات')?></td><td><?=money($r['price_delta'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="small-btn danger">حذف</button></form></td></tr><?php endforeach;?></table></div></section></div></main><?php render_footer();?>
